 "1 list will be saved.": "1টি তালিকা সংরক্ষণ করা হবে।",
 "1. Choose the menu (add more menus if needed) · 2. Enter how many pax to cook · 3. The ingredient list is worked out · 4. Items and quantities are grouped by supplier, ready to order.": "1. মেনু বেছে নিন (দরকার হলে আরও মেনু যোগ করুন) · 2. কত pax রান্না হবে লিখুন · 3. উপকরণের তালিকা হিসাব হয়ে যায় · 4. আইটেম ও পরিমাণ সরবরাহকারী অনুযায়ী সাজানো হয়, অর্ডারের জন্য প্রস্তুত।",
 "1. Verify the outstanding balance": "1. বকেয়া যাচাই করুন",
