 "7 days before": "7 দিন আগে",
 "A completed task is kept in the history and cannot be deleted. Cancel it instead if it was a mistake.": "সম্পন্ন কাজ ইতিহাসে সংরক্ষিত থাকে এবং মুছে ফেলা যায় না। ভুল হয়ে থাকলে বরং এটি বাতিল করুন।",
 "A completed task is part of the history and cannot be edited. Reopen it first.": "সম্পন্ন কাজ ইতিহাসের অংশ এবং সম্পাদনা করা যায় না। আগে এটি আবার চালু করুন।",
 "A cost with the same type, supplier, reference, amount and date already exists for this event. Save anyway only if it is a genuinely separate cost.": "একই ধরন, সরবরাহকারী, রেফারেন্স, অঙ্ক ও তারিখের একটি খরচ এই ইভেন্টে আগেই আছে। এটি সত্যিই আলাদা খরচ হলে তবেই তবু সংরক্ষণ করুন।",
 "A customer named \"{0}\" already exists for this company. Reject this one or change the name first.": "এই কোম্পানির জন্য “{0}” নামে একজন গ্রাহক আগেই আছে। এটি বাতিল করুন বা আগে নাম বদলান।",
 "A decision is needed": "সিদ্ধান্ত প্রয়োজন",
 "A document is already attached. Choose a file only to replace it.": "একটি ডকুমেন্ট আগেই সংযুক্ত আছে। শুধু বদলাতে চাইলে ফাইল বেছে নিন।",
 "A face photo is required as attendance proof.": "উপস্থিতির প্রমাণ হিসেবে মুখের ছবি দিতে হবে।",
 "a file (PDF, Excel or CSV)": "একটি ফাইল (PDF, Excel বা CSV)",
 "A multi-day event can have at most {0} days.": "একটি বহু-দিনের ইভেন্টে সর্বোচ্চ {0} দিন থাকতে পারে।",
 "A part payment is fine: you can request less than the balance and request the rest later. Approval does not mark anything as paid.": "আংশিক পেমেন্ট চলবে: আপনি বকেয়ার চেয়ে কম অনুরোধ করে বাকিটা পরে অনুরোধ করতে পারেন। অনুমোদনে কিছুই পরিশোধিত হিসেবে চিহ্নিত হয় না।",
 "A payment is already being processed for this record.": "এই রেকর্ডের জন্য একটি পেমেন্ট ইতিমধ্যে প্রক্রিয়াধীন আছে।",
 "A payment with the same transaction reference, amount and date is already recorded. Check that this is not a duplicate entry.": "একই লেনদেন রেফারেন্স, পরিমাণ ও তারিখের একটি পেমেন্ট ইতিমধ্যে রেকর্ড করা আছে। এটি যেন ডুপ্লিকেট এন্ট্রি না হয় তা দেখে নিন।",
 "A phone number or an email is needed.": "ফোন নম্বর বা ইমেইল দিতে হবে।",
 "a photo or screenshot": "একটি ছবি বা স্ক্রিনশট",
 "A reason is required for an admin override.": "অ্যাডমিন ওভাররাইডের জন্য কারণ দিতে হবে।",
 "A reason is required to correct attendance.": "উপস্থিতি সংশোধনের জন্য কারণ দিতে হবে।",
 "A reason is required.": "কারণ দিতে হবে।",
 "A recipe called \"{0}\" already exists for this company. Open that recipe instead of creating it again.": "এই কোম্পানির জন্য “{0}” নামে একটি রেসিপি আগেই আছে। নতুন করে না বানিয়ে সেই রেসিপিটি খুলুন।",
 "A request for the same amount is already waiting for approval.": "একই পরিমাণের একটি অনুরোধ ইতিমধ্যে অনুমোদনের অপেক্ষায় আছে।",
 "A supplier invoice can be the cost of one event only, once. Paying it later is not a second cost.": "একটি সরবরাহকারী ইনভয়েস শুধু একটি ইভেন্টের খরচ হতে পারে, একবারই। পরে এটি পরিশোধ করা দ্বিতীয় খরচ নয়।",
 "A task cannot be moved to another company.": "কাজ অন্য কোম্পানিতে স্থানান্তর করা যায় না।",
 "A title is required.": "শিরোনাম দিতে হবে।",
