 "Accept": "গ্রহণ করুন",
 "Accepted": "গৃহীত",
 "Access instructions, load-in time, etc.": "প্রবেশের নির্দেশনা, মাল তোলার সময় ইত্যাদি",
 "Account No.": "অ্যাকাউন্ট নম্বর",
 "Account not found.": "অ্যাকাউন্ট পাওয়া যায়নি।",
 "Acknowledged": "স্বীকৃত",
 "Across all employees you can access.": "আপনি যেসব কর্মীর তথ্য দেখতে পারেন তাদের সবার মিলিয়ে।",
 "Across every catering event you can access.": "আপনি যেসব ক্যাটারিং ইভেন্ট দেখতে পারেন সেগুলোর সব মিলিয়ে।",
