 "Active (inactive accounts are hidden from the payment forms; nothing is deleted)": "সক্রিয় (নিষ্ক্রিয় অ্যাকাউন্ট পেমেন্ট ফর্মে দেখানো হয় না; কিছুই মুছে যায় না)",
