 "Only an admin can correct attendance.": "শুধু অ্যাডমিন উপস্থিতি সংশোধন করতে পারেন।",
 "Only an admin can link a login account to a staff record.": "শুধু অ্যাডমিন কর্মীর রেকর্ডের সাথে লগইন অ্যাকাউন্ট যুক্ত করতে পারেন।",
 "Only an admin can manage the driver list.": "শুধু অ্যাডমিন ড্রাইভারের তালিকা পরিচালনা করতে পারেন।",
 "Only an admin can mark an off day.": "শুধু অ্যাডমিন ছুটির দিন চিহ্নিত করতে পারেন।",
 "Only an admin can set the event location on the map.": "শুধু অ্যাডমিন মানচিত্রে অনুষ্ঠানের স্থান নির্ধারণ করতে পারেন।",
 "Only an approved request can be moved to processing.": "শুধু অনুমোদিত অনুরোধই প্রক্রিয়াধীন অবস্থায় নেওয়া যায়।",
 "Only Finance / Admin users can record payments.": "শুধু ফাইন্যান্স / অ্যাডমিন ব্যবহারকারীরা পেমেন্ট রেকর্ড করতে পারেন।",
 "Only Finance / Admin users of this company can do this.": "শুধু এই কোম্পানির ফাইন্যান্স / অ্যাডমিন ব্যবহারকারীরা এটি করতে পারেন।",
 "Only Finance / Admin users of this company can manage payments and bank details.": "শুধু এই কোম্পানির ফাইন্যান্স / অ্যাডমিন ব্যবহারকারীরা পেমেন্ট ও ব্যাংকের তথ্য পরিচালনা করতে পারেন।",
 "Only Finance / Admin users of this company can record event revenue and costs.": "শুধু এই কোম্পানির ফাইন্যান্স / অ্যাডমিন ব্যবহারকারীরা ইভেন্টের আয় ও খরচ রেকর্ড করতে পারেন।",
