 "That username is already taken.": "ওই ইউজারনেম আগেই নেওয়া হয়েছে।",
 "The AI could not read any details from this file (it may be blurry, cut off or the wrong document type). The file is saved — fill in the fields manually, or try a clearer copy.": "AI এই ফাইল থেকে কোনো তথ্য পড়তে পারেনি (এটি ঝাপসা, কাটা বা ভুল ধরনের ডকুমেন্ট হতে পারে)। ফাইলটি সংরক্ষিত আছে — ফিল্ডগুলো হাতে পূরণ করুন, বা আরও পরিষ্কার কপি দিন।",
 "The amount must be more than 0.": "অঙ্ক 0-এর বেশি হতে হবে।",
 "The assistant couldn't respond just now.": "সহকারী এখনই উত্তর দিতে পারেনি।",
 "The company and category of a payment cannot be changed.": "পেমেন্টের কোম্পানি ও ক্যাটাগরি বদলানো যায় না।",
 "The document is addressed to \"{0}\" but you are saving it under {1}. Check the company (Payment Of) before confirming.": "ডকুমেন্টটি “{0}”-এর নামে, কিন্তু আপনি এটি {1}-এর অধীনে সংরক্ষণ করছেন। নিশ্চিত করার আগে কোম্পানি (যার পেমেন্ট) দেখে নিন।",
 "The email address does not look right.": "ইমেইল ঠিকানাটি ঠিক মনে হচ্ছে না।",
 "The event location is too long.": "অনুষ্ঠানের স্থান খুব বড়।",
 "The event name is too long.": "অনুষ্ঠানের নাম খুব বড়।",
 "The event time is not a valid time.": "অনুষ্ঠানের সময় সঠিক সময় নয়।",
 "The file is too large for the server to accept. Upload a smaller or compressed copy.": "ফাইলটি সার্ভারের জন্য অনেক বড়। ছোট বা কমপ্রেস করা কপি আপলোড করুন।",
 "The first time an event location is used it is looked up on the map automatically. If a driver or part-timer at the venue is told they are too far away, set the exact point here (stand at the venue and use your own position, or paste coordinates or a Google Maps link).": "অনুষ্ঠানের স্থান প্রথমবার ব্যবহার করলে মানচিত্রে স্বয়ংক্রিয়ভাবে খোঁজা হয়। ভেন্যুতে থাকা কোনো ড্রাইভার বা খণ্ডকালীন কর্মীকে যদি বলা হয় তিনি অনেক দূরে, তাহলে এখানে সঠিক বিন্দুটি নির্ধারণ করুন (ভেন্যুতে দাঁড়িয়ে নিজের অবস্থান ব্যবহার করুন, বা স্থানাঙ্ক বা Google Maps লিংক পেস্ট করুন)।",
 "The From date is after the To date, so the list is not filtered.": "“থেকে” তারিখ “পর্যন্ত” তারিখের পরে, তাই তালিকা ফিল্টার করা হয়নি।",
 "The invoice number was not found in the system, so the office will check it.": "ইনভয়েস নম্বরটি সিস্টেমে পাওয়া যায়নি, তাই অফিস এটি যাচাই করবে।",
 "The lines below are grouped by the supplier that supplies them. Each supplier gets one draft purchase order with the item, quantity and unit.": "নিচের লাইনগুলো যে সরবরাহকারী সরবরাহ করে তার অনুযায়ী সাজানো। প্রতিটি সরবরাহকারীর জন্য আইটেম, পরিমাণ ও এককসহ একটি খসড়া ক্রয় আদেশ হবে।",
 "The menu file's {0}-pax figure ({1}) does not match its {2}-pax quantity ×{3} ({4}). Calculated from the {5}-pax quantity.": "মেনু ফাইলের {0}-pax-এর অঙ্ক ({1}) এর {2}-pax পরিমাণ ×{3}-এর ({4}) সাথে মেলে না। {5}-pax পরিমাণ থেকে হিসাব করা হয়েছে।",
 "The name is too long.": "নামটি খুব বড়।",
 "The number on the customer's invoice": "গ্রাহকের ইনভয়েসে থাকা নম্বর",
 "The original clock-in/out times stay in the audit trail.": "মূল ক্লক-ইন/আউটের সময় অডিট ট্রেইলে থাকে।",
 "The OT date cannot be in the future.": "OT-র তারিখ ভবিষ্যতের হতে পারবে না।",
 "The payment checklist contains bank details and is only available to Finance / Admin users of the company.": "পেমেন্ট চেকলিস্টে ব্যাংকের তথ্য আছে এবং এটি শুধু কোম্পানির ফাইন্যান্স / অ্যাডমিন ব্যবহারকারীরা দেখতে পারেন।",
