 "Your login is not linked to a staff record. Ask HR or an admin to link your account to your name.": "আপনার লগইন কোনো কর্মী রেকর্ডের সাথে যুক্ত নয়। আপনার অ্যাকাউন্ট আপনার নামের সাথে যুক্ত করতে HR বা অ্যাডমিনকে বলুন।",
